        AND gdg.gb_dg_dfg_goods_father_id IS NOT NULL

SELECT gb_department_dis_goods_id FROM gb_department_dis_goods AS ddg LEFT JOIN gb_distributer_goods AS dg ON dg.gb_distributer_goods_id = ddg.gb_DDG_dis_goods_id LEFT JOIN gb_distributer_father_goods AS f ON f.gb_distributer_father_goods_id = dg.gb_dg_dfg_goods_father_id LEFT JOIN gb_distributer_father_goods AS g ON g.gb_distributer_father_goods_id = f.gb_dfg_fathers_father_id LEFT JOIN gb_distributer_father_goods AS gg ON gg.gb_distributer_father_goods_id = g.gb_dfg_fathers_father_id
AND ddg.gb_DDG_department_id = #{depId}
AND ddg.gb_DDG_gb_dis_id = #{disId}
AND dg.gb_dg_pull_off = #{pull}
AND dg.gb_dg_dfg_goods_father_id IS NOT NULL
AND dg.gb_dg_dfg_goods_father_id IS NULL
ORDER BY gg.gb_dfg_father_goods_sort, g.gb_dfg_father_goods_sort, f.gb_dfg_father_goods_sort, dg.gb_dg_goods_sort

