ORDER BY greatGrand.gb_dfg_father_goods_sort, great.gb_dfg_father_goods_sort, dfg.gb_dfg_father_goods_sort, dg.gb_dg_goods_sort
LIMIT #{limit} OFFSET #{offset}
) AS base INNER JOIN gb_department_dis_goods AS ddg ON ddg.gb_department_dis_goods_id = base.gb_department_dis_goods_id LEFT JOIN gb_distributer_goods AS dg ON dg.gb_distributer_goods_id = ddg.gb_DDG_dis_goods_id LEFT JOIN gb_distributer_standard AS s ON s.gb_DS_dis_goods_id = dg.gb_distributer_goods_id LEFT JOIN gb_distributer_father_goods AS dfg ON dfg.gb_distributer_father_goods_id = ddg.gb_DDG_dis_goods_father_id LEFT JOIN gb_distributer_father_goods AS great ON great.gb_distributer_father_goods_id = dfg.gb_dfg_fathers_father_id LEFT JOIN gb_distributer_father_goods AS greatGrand ON greatGrand.gb_distributer_father_goods_id = great.gb_dfg_fathers_father_id LEFT JOIN nongxinle.nx_goods AS ng ON ng.nx_goods_id = great.gb_dfg_nx_goods_id LEFT JOIN gb_department_orders AS dor ON dor.gb_DO_dis_goods_id = ddg.gb_DDG_dis_goods_id AND dor.gb_DO_status < #{status} AND dor.gb_DO_status > -1 AND dor.gb_DO_department_id = #{depId} AND dor.gb_DO_order_type != 9 LEFT JOIN gb_department_goods_stock AS inventoryStock ON inventoryStock.gb_dgs_gb_dep_dis_goods_id = ddg.gb_department_dis_goods_id AND inventoryStock.gb_dgs_status > -1 AND inventoryStock.gb_dgs_rest_weight > 0 ORDER BY greatGrand.gb_dfg_father_goods_sort, great.gb_dfg_father_goods_sort, dfg.gb_dfg_father_goods_sort, dg.gb_dg_goods_sort, inventoryStock.gb_dgs_date

SELECT * FROM gb_department_dis_goods AS gddg
LEFT JOIN gb_distributer_goods AS gdg ON gdg.gb_distributer_goods_id = gddg.gb_DDG_dis_goods_id
LEFT JOIN gb_department_goods_stock AS gdgs ON gdgs.gb_dgs_gb_dep_dis_goods_id = gddg.gb_department_dis_goods_id
LEFT JOIN gb_department AS gd ON gd.gb_department_id = gddg.gb_DDG_department_id


        AND gddg.gb_DDG_department_id = #{depId}


        AND gddg.gb_DDG_dis_goods_id = #{disGoodsId}


        AND gddg.gb_DDG_department_father_id = #{depFatherId}


        AND gddg.gb_DDG_dis_goods_father_id = #{disGoodsFatherId}

SELECT gdg.gb_distributer_goods_id
FROM gb_distributer_goods AS gdg
LEFT JOIN gb_distributer_father_goods AS g ON g.gb_distributer_father_goods_id = gdg.gb_dg_dfg_goods_grand_id
LEFT JOIN gb_distributer_father_goods AS gg ON gg.gb_distributer_father_goods_id = g.gb_dfg_fathers_father_id
LEFT JOIN gb_distributer_father_goods AS f ON f.gb_distributer_father_goods_id = gdg.gb_dg_dfg_goods_father_id


        AND gdg.gb_dg_distributer_id = #{disId}


        AND EXISTS (
            SELECT 1 FROM gb_department_dis_goods AS ddg
            WHERE ddg.gb_DDG_dis_goods_id = gdg.gb_distributer_goods_id
            AND ddg.gb_DDG_department_id = #{depId}
        )


        AND gdg.gb_dg_pull_off = #{pull}


        AND gdg.gb_dg_goods_type = #{goodsType}


        AND gdg.gb_dg_control_price = #{price}


        AND gdg.gb_dg_control_fresh = #{fresh}


        AND gdg.gb_dg_gb_supplier_id = #{supplierId}


ORDER BY gg.gb_dfg_father_goods_sort, g.gb_dfg_father_goods_sort, f.gb_dfg_father_goods_sort,
         gdg.gb_dg_goods_sort, gdg.gb_dg_goods_sons_sort, gdg.gb_distributer_goods_id DESC

SELECT * FROM gb_department_dis_goods AS gddg
LEFT JOIN gb_distributer_goods AS gdg ON gdg.gb_distributer_goods_id = gddg.gb_DDG_dis_goods_id
LEFT JOIN gb_department_orders AS dor ON gddg.gb_department_dis_goods_id = dor.gb_DO_dep_dis_goods_id
    AND dor.gb_Do_status < #{orderStatus}
    AND dor.gb_Do_order_type != 9
LEFT JOIN gb_department_goods_stock AS gdgs ON gdgs.gb_dgs_gb_dis_goods_id = gdg.gb_distributer_goods_id
    AND gdgs.gb_dgs_rest_weight > #{restWeight}


        AND gddg.gb_DDG_dis_goods_id = #{disGoodsId}


        AND gddg.gb_DDG_gb_department_id = #{gbDepId}


        AND gddg.gb_DDG_department_id = #{depId}


ORDER BY gdgs.gb_department_goods_stock_id

SELECT COUNT(*)
FROM gb_distributer_goods AS gdg


        AND gdg.gb_dg_distributer_id = #{disId}



        AND gdg.gb_dg_gb_supplier_id = #{supplierId}


        AND gdg.gb_dg_goods_type = #{goodsType}


        AND gdg.gb_dg_control_fresh = 1


        AND gdg.gb_dg_pull_off = 1

SELECT gddg.* FROM gb_department_dis_goods AS gddg LEFT JOIN gb_distributer_goods AS gdg ON gdg.gb_distributer_goods_id = gddg.gb_DDG_dis_goods_id LEFT JOIN gb_distributer_father_goods AS g ON g.gb_distributer_father_goods_id = gddg.gb_DDG_dis_goods_grand_id LEFT JOIN gb_distributer_father_goods AS gg ON gg.gb_distributer_father_goods_id = g.gb_dfg_fathers_father_id LEFT JOIN gb_distributer_father_goods AS ddf ON ddf.gb_distributer_father_goods_id = gddg.gb_DDG_dis_goods_father_id
AND g.gb_dfg_distributer_id = #{disId} AND gg.gb_dfg_distributer_id = #{disId}
AND gdg.gb_dg_gb_supplier_id = #{supplierId}
AND gdg.gb_dg_goods_type = #{goodsType}
AND gdg.gb_dg_control_fresh = 1
AND gdg.gb_dg_pull_off = 1
GROUP BY gddg.gb_department_dis_goods_id ORDER BY gg.gb_dfg_father_goods_sort, g.gb_dfg_father_goods_sort, ddf.gb_dfg_father_goods_sort, gdg.gb_dg_goods_sort, gdg.gb_dg_goods_sons_sort, gddg.gb_department_dis_goods_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT gdg.*, IFNULL(stockStats.goodsStockTotal, 0) as 'goodsStockTotal', IFNULL(stockStats.goodsStockWeightTotal, 0) as 'goodsStockWeightTotal' FROM gb_distributer_goods AS gdg LEFT JOIN gb_distributer_father_goods AS g ON g.gb_distributer_father_goods_id = gdg.gb_dg_dfg_goods_grand_id LEFT JOIN gb_distributer_father_goods AS gg ON gg.gb_distributer_father_goods_id = g.gb_dfg_fathers_father_id LEFT JOIN gb_distributer_father_goods AS f ON f.gb_distributer_father_goods_id = gdg.gb_dg_dfg_goods_father_id LEFT JOIN ( SELECT gb_dgs_gb_dis_goods_id, SUM(gb_dgs_rest_subtotal) as goodsStockTotal, SUM(gb_dgs_rest_weight) as goodsStockWeightTotal FROM gb_department_goods_stock WHERE gb_dgs_rest_weight > 0 GROUP BY gb_dgs_gb_dis_goods_id ) AS stockStats ON stockStats.gb_dgs_gb_dis_goods_id = gdg.gb_distributer_goods_id
AND gdg.gb_dg_distributer_id = #{disId}
AND gdg.gb_dg_gb_supplier_id = #{supplierId}
AND gdg.gb_dg_goods_type = #{goodsType}
AND gdg.gb_dg_control_fresh = 1
AND gdg.gb_dg_pull_off = 1
ORDER BY gg.gb_dfg_father_goods_sort, g.gb_dfg_father_goods_sort, f.gb_dfg_father_goods_sort, gdg.gb_dg_goods_sort, gdg.gb_dg_goods_sons_sort, gdg.gb_distributer_goods_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT gdg.*, IFNULL(MAX(stockStats.goodsStockTotal), 0) as 'goodsStockTotal', IFNULL(MAX(stockStats.goodsStockWeightTotal), 0) as 'goodsStockWeightTotal', MAX(gg.gb_dfg_father_goods_sort) as 'sort1', MAX(g.gb_dfg_father_goods_sort) as 'sort2', MAX(f.gb_dfg_father_goods_sort) as 'sort3' FROM gb_department_dis_goods AS gddg LEFT JOIN gb_distributer_goods AS gdg ON gdg.gb_distributer_goods_id = gddg.gb_DDG_dis_goods_id LEFT JOIN gb_distributer_father_goods AS g ON g.gb_distributer_father_goods_id = gddg.gb_DDG_dis_goods_grand_id LEFT JOIN gb_distributer_father_goods AS gg ON gg.gb_distributer_father_goods_id = g.gb_dfg_fathers_father_id LEFT JOIN gb_distributer_father_goods AS f ON f.gb_distributer_father_goods_id = gddg.gb_DDG_dis_goods_father_id LEFT JOIN ( SELECT gb_dgs_gb_dis_goods_id, SUM(gb_dgs_rest_subtotal) as goodsStockTotal, SUM(gb_dgs_rest_weight) as goodsStockWeightTotal FROM gb_department_goods_stock WHERE gb_dgs_rest_weight > 0 GROUP BY gb_dgs_gb_dis_goods_id ) AS stockStats ON stockStats.gb_dgs_gb_dis_goods_id = gdg.gb_distributer_goods_id
AND gddg.gb_DDG_department_father_id = #{depFatherId}
AND gddg.gb_DDG_department_id = #{depId}
AND gddg.gb_DDG_gb_dis_id = #{disId}
AND gddg.gb_DDG_gb_supplier_id = #{supplierId}
AND gddg.gb_DDG_goods_type = #{goodsType}
AND gdg.gb_dg_control_fresh = 1
GROUP BY gdg.gb_distributer_goods_id ORDER BY sort1, sort2, sort3, gdg.gb_dg_goods_sort, gdg.gb_dg_goods_sons_sort, gdg.gb_distributer_goods_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT ddg.*, gdgs.*, dg.*, gds.*, da.*, dor.*, du.*, gd.* FROM gb_department_dis_goods AS ddg LEFT JOIN gb_department_goods_stock AS gdgs ON gdgs.gb_dgs_gb_dep_dis_goods_id = ddg.gb_department_dis_goods_id AND gdgs.gb_dgs_rest_weight > 0 AND gdgs.gb_dgs_status > -1 LEFT JOIN gb_distributer_goods AS dg ON dg.gb_distributer_goods_id = ddg.gb_DDG_dis_goods_id LEFT JOIN gb_distributer_standard AS gds ON gds.gb_DS_dis_goods_id = dg.gb_distributer_goods_id LEFT JOIN gb_distributer_alias AS da ON da.gb_DA_dis_goods_id = dg.gb_distributer_goods_id LEFT JOIN gb_department_orders AS dor ON dor.gb_DO_dis_goods_id = dg.gb_distributer_goods_id AND dor.gb_DO_status < 2 AND dor.gb_DO_status > -1 AND dor.gb_DO_department_id = #{depId} LEFT JOIN gb_department_user AS du ON du.gb_department_user_id = dor.gb_DO_order_user_id LEFT JOIN gb_department AS gd ON gd.gb_department_id = ddg.gb_DDG_gb_department_id
AND ddg.gb_DDG_department_id = #{depId}
AND (
OR ddg.gb_DDG_dep_goods_name LIKE CONCAT('%', #{searchStr}, '%') OR da.gb_DA_alias_name LIKE CONCAT('%', #{searchStr}, '%') OR ddg.gb_DDG_dep_goods_pinyin LIKE CONCAT('%', #{searchStr}, '%') OR ddg.gb_DDG_dep_goods_py LIKE CONCAT('%', #{searchStr}, '%')
OR ddg.gb_DDG_dep_goods_pinyin LIKE CONCAT('%', #{searchPinyin}, '%') OR ddg.gb_DDG_dep_goods_py LIKE CONCAT('%', #{searchPinyin}, '%') OR da.gb_DA_alias_name LIKE CONCAT('%', #{searchPinyin}, '%')
)
AND dg.gb_dg_is_self_control = #{isSelf}
AND dg.gb_dg_pull_off = #{pull}
AND dg.gb_dg_dfg_goods_father_id IS NOT NULL
AND dg.gb_dg_dfg_goods_father_id IS NULL
ORDER BY dg.gb_dg_goods_sort
